/**
 * Verified certification content. Every entry links to the original PDF and a
 * WebP preview generated by `scripts/optimize-images.mjs`.
 */
export type Certification = {
  title: string;
  issuer: string;
  date: string;
  description: string;
  skills: string[];
  previewImage: string;
  previewWidth: number;
  previewHeight: number;
  pdfUrl: string;
  featured?: boolean;
};

export type CertificationCategory = {
  id: string;
  category: string;
  subtitle: string;
  icon: "ai" | "cloud" | "code";
  spans: string[];
  certs: Certification[];
};

